import numpy as np

# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: This algorithm uses a simple random search strategy to explore the search space.
# Search state: The search state consists of the current best solution (best_x, best_y).
# Candidate generation: New candidate solutions are generated by sampling uniformly within the search bounds.
# Selection and replacement: The best candidate solution is compared to the current best solution, and the better one is kept.
# Adaptation: There is no adaptation mechanism in this algorithm.
# Exploration mechanisms: The random generation of candidate solutions provides exploration.
# Exploitation mechanisms: The selection of the best solution provides a form of exploitation.
# Boundary handling: Candidate solutions that fall outside the search bounds are regenerated until a valid solution is found.
# Budget strategy: The algorithm stops when the evaluation budget is exhausted.
# Closest known influences: This algorithm is a basic random search strategy, which is a common baseline for black-box optimization.
# Novelty or unusual aspects: There are no novel or unusual aspects to this algorithm.
# Failure modes: The algorithm may struggle to find good solutions in high-dimensional problems or problems with complex landscapes, as it relies solely on random exploration.
# ALGORITHM_ANALYSIS_NOTE_END

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim
        self.best_x = None
        self.best_y = float('inf')
        self.evals = 0

    def __call__(self, func):
        while self.evals < self.budget:
            # Generate a new candidate solution
            x = np.random.uniform(func.lower, func.upper, self.dim)

            # Evaluate the candidate solution
            y = func(x)
            self.evals += 1

            # Update the best solution if necessary
            if y < self.best_y:
                self.best_x = x
                self.best_y = y

        return self.best_x, self.best_y
